     1	import { ERROR_CODES, LedgerError } from './errors.mjs';
     2	
     3	/**
     4	 * Tokenizes a filter expression into typed tokens.
     5	 *
     6	 * @param {string} expr
     7	 * @returns {Array<{ type: string, value: any }>}
     8	 */
     9	export function tokenizeDsl(expr) {
    10	  if (typeof expr !== 'string' || !expr.trim()) {
    11	    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Filter expression must be a non-empty string');
    12	  }
    13	  const tokens = [];
    14	  let i = 0;
    15	  while (i < expr.length) {
    16	    const ch = expr[i];
    17	    if (/\s/.test(ch)) {
    18	      i += 1;
    19	      continue;
    20	    }
    21	    if (ch === '(' || ch === ')' || ch === ',') {
    22	      tokens.push({ type: ch, value: ch });
    23	      i += 1;
    24	      continue;
    25	    }
    26	    if (ch === '"') {
    27	      let j = i + 1;
    28	      let buf = '';
    29	      while (j < expr.length) {
    30	        if (expr[j] === '"' && expr[j - 1] !== '\\') break;
    31	        buf += expr[j];
    32	        j += 1;
    33	      }
    34	      if (j >= expr.length) {
    35	        throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Unterminated string literal');
    36	      }
    37	      tokens.push({ type: 'STRING', value: buf });
    38	      i = j + 1;
    39	      continue;
    40	    }
    41	    const two = expr.slice(i, i + 2);
    42	    if (two === '==' || two === '!=' || two === '>=' || two === '<=') {
    43	      tokens.push({ type: 'OP', value: two });
    44	      i += 2;
    45	      continue;
    46	    }
    47	    if (ch === '>' || ch === '<') {
    48	      tokens.push({ type: 'OP', value: ch });
    49	      i += 1;
    50	      continue;
    51	    }
    52	    if (/[0-9-]/.test(ch)) {
    53	      const m = /^-?\d+(?:\.\d+)?/.exec(expr.slice(i));
    54	      if (m) {
    55	        tokens.push({ type: 'NUMBER', value: Number(m[0]) });
    56	        i += m[0].length;
    57	        continue;
    58	      }
    59	    }
    60	    const ident = /^[A-Za-z_][A-Za-z0-9_.]*/.exec(expr.slice(i));
    61	    if (ident) {
    62	      const word = ident[0];
    63	      const upper = word.toUpperCase();
    64	      if (upper === 'AND' || upper === 'OR' || upper === 'NOT') {
    65	        tokens.push({ type: upper, value: upper });
    66	      } else if (upper === 'TRUE' || upper === 'FALSE') {
    67	        tokens.push({ type: 'BOOLEAN', value: upper === 'TRUE' });
    68	      } else if (upper === 'NULL') {
    69	        tokens.push({ type: 'NULL', value: null });
    70	      } else {
    71	        tokens.push({ type: 'IDENT', value: word });
    72	      }
    73	      i += word.length;
    74	      continue;
    75	    }
    76	    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected character: ${ch}`);
    77	  }
    78	  return tokens;
    79	}
    80	
    81	function resolveField(obj, pathStr) {
    82	  const parts = String(pathStr).split('.');
    83	  let cur = obj;
    84	  for (const part of parts) {
    85	    if (cur === null || cur === undefined || typeof cur !== 'object') return undefined;
    86	    cur = cur[part];
    87	  }
    88	  return cur;
    89	}
    90	
    91	/**
    92	 * Compiles a filter expression string into `(event) => boolean`.
    93	 *
    94	 * @param {string} expr
    95	 * @returns {(event: object) => boolean}
    96	 */
    97	export function compileFilter(expr) {
    98	  const tokens = tokenizeDsl(expr);
    99	  let pos = 0;
   100	
   101	  function peek() {
   102	    return tokens[pos] || null;
   103	  }
   104	
   105	  function consume(expectedType = null) {
   106	    const tok = tokens[pos];
   107	    if (!tok || (expectedType && tok.type !== expectedType)) {
   108	      throw new LedgerError(
   109	        ERROR_CODES.ERR_DSL_SYNTAX,
   110	        `Expected ${expectedType || 'token'}, got ${tok ? tok.type : 'EOF'}`
   111	      );
   112	    }
   113	    pos += 1;
   114	    return tok;
   115	  }
   116	
   117	  function parsePrimary() {
   118	    const tok = peek();
   119	    if (!tok) throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Unexpected end of filter');
   120	    if (tok.type === '(') {
   121	      consume('(');
   122	      const inner = parseExpr();
   123	      consume(')');
   124	      return inner;
   125	    }
   126	    if (tok.type === 'NOT') {
   127	      consume('NOT');
   128	      const inner = parsePrimary();
   129	      return (evt) => !inner(evt);
   130	    }
   131	    const fieldTok = consume('IDENT');
   132	    const opTok = consume('OP');
   133	    const valTok = consume();
   134	    if (!['STRING', 'NUMBER', 'BOOLEAN', 'NULL'].includes(valTok.type)) {
   135	      throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected literal token: ${valTok.type}`);
   136	    }
   137	    const target = valTok.value;
   138	    return (evt) => {
   139	      const actual = resolveField(evt, fieldTok.value);
   140	      switch (opTok.value) {
   141	        case '==': return actual === target;
   142	        case '!=': return actual !== target;
   143	        case '>': return actual > target;
   144	        case '>=': return actual >= target;
   145	        case '<': return actual < target;
   146	        case '<=': return actual <= target;
   147	        default: return false;
   148	      }
   149	    };
   150	  }
   151	
   152	  function parseExpr() {
   153	    let left = parsePrimary();
   154	    while (peek() && (peek().type === 'AND' || peek().type === 'OR')) {
   155	      const op = consume().type;
   156	      const right = parsePrimary();
   157	      const prevLeft = left;
   158	      left = op === 'AND'
   159	        ? (evt) => prevLeft(evt) && right(evt)
   160	        : (evt) => prevLeft(evt) || right(evt);
   161	    }
   162	    return left;
   163	  }
   164	
   165	  const fn = parseExpr();
   166	  if (pos !== tokens.length) {
   167	    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected trailing token ${tokens[pos].value}`);
   168	  }
   169	  return fn;
   170	}
