     6	/**
     7	 * Builds an invoice from usage rows and credit grants.
     8	 *
     9	 * @param {object} params
    10	 * @returns {object}
    11	 */
    12	export function buildInvoice({
    13	  invoiceId,
    14	  accountId,
    15	  currency = 'USD',
    16	  usageRows = [],
    17	  grants = [],
    18	  asOfMs = 0
    19	} = {}) {
    20	  const lineItems = [];
    21	  let usageSubtotalCents = 0;
    22	
    23	  for (const row of usageRows) {
    24	    const { totalCents } = computeGraduatedCharge(row.units, row.tiers);
    25	    usageSubtotalCents += totalCents;
    26	    lineItems.push({
    27	      metric: row.metric,
    28	      units: row.units,
    29	      amountCents: totalCents
    30	    });
    31	  }
    32	
    33	  const creditResult = applyCredits(usageSubtotalCents, grants, asOfMs);
    34	  const totalDueCents = creditResult.remainingChargeCents;
    35	  const status = INVOICE_STATUS.FINALIZED;
    36	  const wireDigest = encodeFrozenWireDigest({
    37	    invoiceId,
    38	    accountId,
    39	    currency,
    40	    totalDueCents,
    41	    status
    42	  });
    43	
    44	  return {
    45	    invoiceId,
    46	    accountId,
    47	    currency,
    48	    status,
    49	    lineItems,
    50	    usageSubtotalCents,
    51	    appliedCreditsCents: creditResult.appliedCents,
    52	    creditAllocations: creditResult.allocations,
    53	    totalDueCents,
    54	    wireDigest
    55	  };
    56	}
