=== src/frozenWire.mjs
     1	import { WIRE_SCHEMA_VERSION } from './constants.mjs';
     2	
     3	/**
     4	 * Legacy LP-WIRE-V1 deterministic 32-bit FNV-1a digest serializer.
     5	 * FROZEN CONTRACT: downstream settlement consumers rely on exact byte output.
     6	 *
     7	 * @param {object} summary
     8	 * @returns {string}
     9	 */
    10	export function encodeFrozenWireDigest(summary = {}) {
    11	  const invoiceId = String(summary.invoiceId || '');
    12	  const accountId = String(summary.accountId || '');
    13	  const currency = String(summary.currency || 'USD');
    14	  const totalDueCents = Math.trunc(Number(summary.totalDueCents || 0));
    15	  const status = String(summary.status || 'FINALIZED');
    16	  const canonical = `${WIRE_SCHEMA_VERSION}|${invoiceId}|${accountId}|${currency}|${totalDueCents}|${status}`;
    17	
    18	  let hash = 0x811c9dc5;
    19	  for (let i = 0; i < canonical.length; i += 1) {
    20	    hash ^= canonical.charCodeAt(i);
    21	    hash = Math.imul(hash, 0x01000193);
    22	  }
    23	  const hex = (hash >>> 0).toString(16).padStart(8, '0');
    24	  return `${WIRE_SCHEMA_VERSION}:${hex}:${totalDueCents}`;
    25	}
