     3	/**
     4	 * Computes graduated (marginal/tiered) usage charges.
     5	 *
     6	 * @param {number} units
     7	 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
     8	 * @returns {{ totalCents: number, breakdown: Array<{ tierIndex: number, upTo: number | null, units: number, unitRateCents: number, subtotalCents: number }> }}
     9	 */
    10	export function computeGraduatedCharge(units, tiers) {
    11	  if (!Array.isArray(tiers) || tiers.length === 0) {
    12	    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
    13	  }
    14	  if (!Number.isFinite(units) || units < 0) {
    15	    return { totalCents: 0, breakdown: [] };
    16	  }
    17	
    18	  let prevUpTo = 0;
    19	  let totalCents = 0;
    20	  const breakdown = [];
    21	
    22	  for (let i = 0; i < tiers.length; i += 1) {
    23	    const tier = tiers[i];
    24	    const cap = tier.upTo === null || tier.upTo === undefined || tier.upTo === Infinity ? Infinity : tier.upTo;
    25	    if (units <= prevUpTo && i > 0) break;
    26	
    27	    const bounded = Math.min(units, cap);
    28	    const bandUnits = Math.max(0, bounded - prevUpTo + (prevUpTo > 0 ? 1 : 0));
    29	    const subtotalCents = Math.floor(bandUnits * tier.unitRateCents);
    30	    totalCents += subtotalCents;
    31	    breakdown.push({
    32	      tierIndex: i,
    33	      upTo: cap === Infinity ? null : cap,
    34	      units: bandUnits,
    35	      unitRateCents: tier.unitRateCents,
    36	      subtotalCents
    37	    });
    38	    if (cap === Infinity) break;
    39	    prevUpTo = cap;
    40	  }
    41	
    42	  return { totalCents, breakdown };
    43	}
