    45	/**
    46	 * Computes volume (all-units-at-matched-tier-rate) usage charges.
    47	 *
    48	 * @param {number} units
    49	 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
    50	 * @returns {{ totalCents: number, matchedTierIndex: number, unitRateCents: number }}
    51	 */
    52	export function computeVolumeCharge(units, tiers) {
    53	  if (!Array.isArray(tiers) || tiers.length === 0) {
    54	    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
    55	  }
    56	  if (!Number.isFinite(units) || units < 0) {
    57	    throw new LedgerError(ERROR_CODES.ERR_NEGATIVE_UNITS, 'units must be >= 0');
    58	  }
    59	  if (units === 0) {
    60	    return { totalCents: 0, matchedTierIndex: 0, unitRateCents: tiers[0].unitRateCents };
    61	  }
    62	
    63	  for (let i = 0; i < tiers.length; i += 1) {
    64	    const cap = tiers[i].upTo === null || tiers[i].upTo === undefined ? Infinity : tiers[i].upTo;
    65	    if (units <= cap) {
    66	      return {
    67	        totalCents: Math.round(units * tiers[i].unitRateCents),
    68	        matchedTierIndex: i,
    69	        unitRateCents: tiers[i].unitRateCents
    70	      };
    71	    }
    72	  }
    73	  const lastIdx = tiers.length - 1;
    74	  return {
    75	    totalCents: Math.round(units * tiers[lastIdx].unitRateCents),
    76	    matchedTierIndex: lastIdx,
    77	    unitRateCents: tiers[lastIdx].unitRateCents
    78	  };
    79	}
